before:
makeSettings takes no arguments and returns the outer frozen object. Object.getOwnPropertyDescriptor reads one own property’s descriptor, or undefined if missing; its writable flag reports the rule. The "use strict" directive makes assigning the read-only version throw TypeError instead of silently doing nothing.
```javascript
"use strict";
function makeSettings() {
  const settings = {theme: {dark: false}};
  Object.defineProperty(settings, "version", {
    value: 1, writable: false, enumerable: true, configurable: false
  });
  return Object.freeze(settings);
}
const settings = makeSettings();
console.log(Object.getOwnPropertyDescriptor(settings, "version").writable);
try { settings.version = 2; }
catch (error) { console.log(error instanceof TypeError); }
settings.theme.dark = true;
console.log(settings.version, settings.theme.dark);
```
Output: false; true; 1 true. The nested dark assignment still succeeds. Object.isFrozen(object) returns whether that object is frozen, without changing it. With settings above, this call prints true false:
```javascript
console.log(Object.isFrozen(settings), Object.isFrozen(settings.theme));
```

after:
Here is the complete example.
```javascript
"use strict";
function makeSettings() {
  const settings = {theme: {dark: false}};
  Object.defineProperty(settings, "version", {
    value: 1, writable: false, enumerable: true, configurable: false
  });
  return Object.freeze(settings);
}
const settings = makeSettings();
console.log(Object.getOwnPropertyDescriptor(settings, "version").writable);
try { settings.version = 2; }
catch (error) { console.log(error instanceof TypeError); }
settings.theme.dark = true;
console.log(settings.version, settings.theme.dark);
console.log(Object.isFrozen(settings), Object.isFrozen(settings.theme));
```
Output:
```text
false
true
1 true
true false
```
`getOwnPropertyDescriptor` reads the version property's rules. In strict mode, assigning to this read-only property throws a TypeError.

Changing `theme.dark` still works. `Object.isFrozen` confirms that only the outer object is frozen.
